#define RALPH_STATE_TITLE 0
#define RALPH_STATE_GAME 1
#define RALPH_STATE_GAME_OVER 2
#define RALPH_STATE_END_GAME 3

#define RALPH_NB_FENTRES 18
#define RALPH_NB_LINES 6
#define RALPH_LIFE_FENTRE 100
#define RALPH_HIT_RALPH 4

int ralphState;

// Flattened "Fenetre {life,x,y}" array (real upstream NB_FENTRES+1 = 19
// entries - the last one, index RALPH_NB_FENTRES, is the rooftop itself).
int ralphFenLife[19];
int ralphFenX[19];
int ralphFenY[19];

// Flattened "Mobile ralph {status,x,y}".
int ralphX;
int ralphY;
int ralphStatus;

int ralphCamX;
int ralphCamY;

int ralphIndexFenetre;

// Real upstream `int roofLevel(int y)` - 47..36 is ground level, every
// further 12px is one new floor level up.
int ralphRoofLevel( int y )
{
    return ( y - 47 ) / 12;
}

// Real upstream `const byte * chooseSprite(int life)`.
int* ralphChooseSprite( int life )
{
    if( life < 10 ) return ralphWindows10Bitmap;
    if( life < 50 ) return ralphWindows50Bitmap;
    if( life < 99 ) return ralphWindows99Bitmap;
    return ralphWindows100Bitmap;
}

// Real upstream `initWindow()` - 3 windows per line, RALPH_NB_LINES lines,
// plus the rooftop's own real triple-life "window" at the end.
void ralphInitWindow()
{
    int i;
    int y;
    int numFenetre;

    for( i = 0; i < RALPH_NB_LINES; i = i + 1 )
    {
        y = 25 - ( 12 * i );
        numFenetre = i * 3;

        ralphFenLife[ numFenetre ] = RALPH_LIFE_FENTRE;
        ralphFenX[ numFenetre ] = 28;
        ralphFenY[ numFenetre ] = y;

        ralphFenLife[ numFenetre + 1 ] = RALPH_LIFE_FENTRE;
        ralphFenX[ numFenetre + 1 ] = 36;
        ralphFenY[ numFenetre + 1 ] = y;

        ralphFenLife[ numFenetre + 2 ] = RALPH_LIFE_FENTRE;
        ralphFenX[ numFenetre + 2 ] = 44;
        ralphFenY[ numFenetre + 2 ] = y;
    }

    ralphFenLife[ RALPH_NB_FENTRES ] = RALPH_LIFE_FENTRE * 3;
    ralphFenX[ RALPH_NB_FENTRES ] = 36;
    ralphFenY[ RALPH_NB_FENTRES ] = -48;
}

// Real upstream `drawWindow()`.
void ralphDrawWindow()
{
    int i;
    for( i = 0; i < RALPH_NB_FENTRES; i = i + 1 )
    {
        gbDrawBitmap( ralphFenX[ i ] - ralphCamX, ralphFenY[ i ] - ralphCamY, ralphChooseSprite( ralphFenLife[ i ] ) );
    }
}

// Real upstream `drawWord()` (real "World", a typo throughout upstream's
// own `world.ino` - corrected in this port's own internal function name
// only, see this file's own header comment).
void ralphDrawWorld()
{
    int x;

    gbDrawLine( 0, 47 - ralphCamY, 84, 47 - ralphCamY );
    x = 20 - ralphCamX;
    gbDrawBitmap( x, 36 - ralphCamY, ralphGroundFloorBitmap );
    gbDrawBitmap( x, -1 - ralphCamY, ralphFloorsBitmap );
    gbDrawBitmap( x, -37 - ralphCamY, ralphFloorsBitmap );

    if( ralphFenLife[ RALPH_NB_FENTRES ] < 30 )
    {
        gbDrawBitmap( x, -48 - ralphCamY, ralphRoofTop10Bitmap );
    }
    else if( ralphFenLife[ RALPH_NB_FENTRES ] < 180 )
    {
        gbDrawBitmap( x, -48 - ralphCamY, ralphRoofTop50Bitmap );
    }
    else if( ralphFenLife[ RALPH_NB_FENTRES ] < 270 )
    {
        gbDrawBitmap( x, -48 - ralphCamY, ralphRoofTop99Bitmap );
    }
    else
    {
        gbDrawBitmap( x, -48 - ralphCamY, ralphRoofTop100Bitmap );
    }
}

// Real upstream `initRalph()`.
void ralphInitRalph()
{
    ralphY = 32;
    ralphX = 2;
    ralphStatus = 0;
}

// Real upstream `drawRalph()`.
void ralphDrawRalph()
{
    switch( ralphStatus )
    {
    case 3: // climbing between floors
        gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap );
        // falls through to case 0 - real upstream double-draw quirk, see
        // this file's own header comment
    case 0: // idle
        gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap );
        break;

    case 1: // punch
        if( gbFrameCount % 8 > 3 )
        {
            gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphPunchBitmap );
        }
        else
        {
            gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap );
        }
        break;

    case 2: // walk
        if( gbFrameCount % 8 > 3 )
        {
            gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphWalk1Bitmap );
        }
        else
        {
            gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphWalk2Bitmap );
        }
        break;

    case 4: // fall (end-game only) - real upstream cycles all 4 rotations
        if( gbFrameCount % 20 > 14 )
        {
            gbDrawBitmap( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap );
        }
        else if( gbFrameCount % 20 > 9 )
        {
            gbDrawBitmapRotated( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap, 1, 0 );
        }
        else if( gbFrameCount % 20 > 4 )
        {
            gbDrawBitmapRotated( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap, 2, 0 );
        }
        else
        {
            gbDrawBitmapRotated( ralphX - ralphCamX, ralphY - ralphCamY, ralphIdleBitmap, 3, 0 );
        }
        break;
    }
}

// Real upstream `fallRalph()`.
void ralphFallRalph()
{
    if( ralphY < 32 )
    {
        ralphY = ralphY + 1;
    }
    else
    {
        ralphStatus = 0;
    }
}

// Real upstream `updateRalph()` - picks the current target window (the
// weakest one on the lowest still-standing line, or the rooftop once
// every real window is broken), then either punches it, walks toward it,
// or climbs to its floor level.
void ralphUpdateRalph()
{
    int i;

    if( ralphStatus == 1 )
    {
        ralphFenLife[ ralphIndexFenetre ] = ralphFenLife[ ralphIndexFenetre ] - RALPH_HIT_RALPH;

        if( ralphFenLife[ ralphIndexFenetre ] <= 0 )
        {
            ralphFenLife[ ralphIndexFenetre ] = 0;
            ralphStatus = 0;
            if( ralphIndexFenetre == RALPH_NB_FENTRES )
            {
                ralphState = RALPH_STATE_END_GAME;
            }
        }
    }
    else if( ralphStatus == 4 )
    {
        ralphFallRalph();
    }
    else
    {
        for( i = 0; i < RALPH_NB_FENTRES; i = i + 1 )
        {
            if( i == ( RALPH_NB_FENTRES - 1 ) )
            {
                ralphIndexFenetre = i;
                break;
            }
            if( ralphFenLife[ i ] < 30 )
            {
                if( ralphFenLife[ i ] > ralphFenLife[ i + 1 ] )
                {
                    ralphIndexFenetre = i;
                    break;
                }
            }
            else
            {
                ralphIndexFenetre = i;
                break;
            }
        }

        if( ralphFenLife[ ralphIndexFenetre ] <= 0 )
        {
            // every regular window is down - go to the rooftop
            ralphIndexFenetre = RALPH_NB_FENTRES;
        }

        // Ralph goes to the selected window or the rooftop
        if( ralphStatus != 3 && gbCollidePointRect( ralphX + 7, ralphY + 7, ralphFenX[ ralphIndexFenetre ], ralphFenY[ ralphIndexFenetre ], 7, 9 ) )
        {
            ralphStatus = 1;
        }
        else
        {
            if( ralphStatus != 3 && ( ralphX + 4 ) < ralphFenX[ ralphIndexFenetre ] )
            {
                ralphStatus = 2;
                ralphX = ralphX + 1;
            }
            else if( ralphStatus != 3 && ( ralphX + 4 ) > ralphFenX[ ralphIndexFenetre ] )
            {
                ralphStatus = 2;
                ralphX = ralphX - 1;
            }
            else if( ralphRoofLevel( ralphY + 15 ) > ralphRoofLevel( ralphFenY[ ralphIndexFenetre ] ) )
            {
                ralphStatus = 3;
                ralphY = ralphY - 1;
            }
            else if( ralphRoofLevel( ralphY + 15 ) < ralphRoofLevel( ralphFenY[ ralphIndexFenetre ] ) )
            {
                ralphStatus = 3;
                ralphY = ralphY + 1;
            }
            else
            {
                ralphStatus = 0;
            }
        }
    }
}

// Real upstream `updateEndGameRalph()` - Ralph walks right off the
// rooftop, then falls back down to ground level, then the game ends.
void ralphUpdateEndGameRalph()
{
    if( ralphX < 70 )
    {
        ralphX = ralphX + 1;
    }
    else if( ralphY < 32 )
    {
        ralphStatus = 4;
        ralphFallRalph();
    }
    else
    {
        ralphState = RALPH_STATE_GAME_OVER;
    }
}

// Real upstream `initGame()` (real `gb.battery.show = false;` has no
// equivalent here - see this file's own header comment).
void ralphInitGame()
{
    ralphInitWindow();
    ralphInitRalph();
    ralphCamX = 0;
    ralphCamY = 0;
    ralphState = RALPH_STATE_GAME;
}

void ralphUpdateTitle()
{
    gbDrawBitmap( 10, 0, ralphLogoBitmap );
    gbCursorX = 28;
    gbCursorY = 40;
    gbPrintString( "PRESS A" );

    if( gbPressed( BTN_A ) )
    {
        ralphInitGame();
    }
}

void ralphUpdateGameOver()
{
    if( gbPressed( BTN_A ) || gbPressed( BTN_B ) )
    {
        ralphInitGame();
    }
    gbDrawBitmap( 0, 0, ralphGameoverBitmap );
}

void gameRalph_init()
{
    gbBegin();
    ralphState = RALPH_STATE_TITLE;
}

void gameRalph_update()
{
    if( !gbUpdate() ) return;

    if( ralphState != RALPH_STATE_TITLE && gbPressed( BTN_C ) )
    {
        ralphState = RALPH_STATE_TITLE;
    }

    if( ralphState == RALPH_STATE_TITLE )
    {
        ralphUpdateTitle();
    }
    else if( ralphState == RALPH_STATE_GAME )
    {
        ralphDrawWorld();
        ralphDrawWindow();
        ralphDrawRalph();

        ralphUpdateRalph();

        if( gbPressed( BTN_UP ) )
        {
            ralphCamY = ralphCamY - 1;
        }
        else if( gbPressed( BTN_DOWN ) )
        {
            ralphCamY = ralphCamY + 1;
        }

        if( gbPressed( BTN_LEFT ) )
        {
            ralphCamX = ralphCamX - 1;
        }
        else if( gbPressed( BTN_RIGHT ) )
        {
            ralphCamX = ralphCamX + 1;
        }
    }
    else if( ralphState == RALPH_STATE_GAME_OVER )
    {
        ralphUpdateGameOver();
    }
    else if( ralphState == RALPH_STATE_END_GAME )
    {
        ralphDrawWorld();
        ralphDrawWindow();
        ralphDrawRalph();

        ralphUpdateEndGameRalph();
    }

    gbRenderFrame();
}
